"""Deterministic Markdown rendering of a pipeline report (aggregate values only)."""

from __future__ import annotations

from typing import Any


def _f(x: Any, digits: int = 4) -> str:
    if isinstance(x, bool) or not isinstance(x, int | float):
        return str(x)
    if isinstance(x, int):
        return str(x)
    if x == 0:
        return "0"
    return f"{x:.{digits}g}"


def render(r: dict[str, Any]) -> str:
    L: list[str] = []
    a = L.append
    a(f"# External-source diagnostic report: `{r['source_id']}`")
    a("")
    a("<!-- GENERATED by `dbs external run`; regenerate rather than edit. -->")
    a("")
    a(
        f"**Outcome:** `{r['outcome']}` · pipeline `{r['pipeline']}` · adapter `{r['adapter']}` · "
        + ", ".join(f"{k} {v}" for k, v in r["environment"].items())
    )
    a("")
    a("> Aggregate pipeline diagnostics of **manufacturer-processed** signals. Not laser accuracy,")
    a("> not reference truth, not athlete assessment, not admitted benchmark data.")
    a("")
    a("## Stages")
    a("")
    a("| Stage | Status | Detail |")
    a("| -- | -- | -- |")
    for s in r["stages"]:
        a(f"| {s['name']} | **{s['status']}** | {s['detail']} |")
    a("")
    if "source" in r:
        src = r["source"]
        a("## Source")
        a("")
        a(
            f"`{src['repository']}` @ `{src['pinned_ref']}` · `{src['data_path']}` · "
            f"{src['data_size_bytes']} B · SHA-256 `{src['data_sha256']}` · "
            f"Git blob `{src['git_blob_sha1']}`"
        )
        a("")
    if "records" in r and not r["records"]["committed_default_root"]:
        a("> **WARNING: UNREVIEWED RECORDS.** " + r["records"]["note"] + ".")
        a("")
    if "rights" in r:
        rt = r["rights"]
        a("## Rights")
        a("")
        a(
            f"License `{rt['license_id']}` (evidence verified: {rt['license_evidence_verified']}); "
            f"measurement-data rights **{rt['measurement_data_rights']}**; consent "
            f"**{rt['participant_consent']}**; minors possible {rt['minors_possible']}; canonical "
            f"admission **{rt['canonical_admission']}**; redistribution "
            f"{'allowed' if rt['redistribution_allowed'] else '**not allowed**'}."
        )
        a("")
        for b in rt["blockers"]:
            a(f"* BLOCKER: {b}")
        a("")
    if "signal_stages" in r:
        a("## Signal stages")
        a("")
        a("| Source column | Channel | Stage | Meaning |")
        a("| -- | -- | -- | -- |")
        for c in r["signal_stages"]:
            a(f"| `{c['source_column']}` | `{c['channel']}` | {c['stage']} | {c['meaning']} |")
        a("")
        a(
            "Package-derived (documented in `data-raw/laser-gun-data.R`, **not ingested**): "
            + "; ".join(f"`{k}`: {v}" for k, v in r["package_derived_not_ingested"].items())
        )
        a("")
    if "profile" in r:
        a("## Source profile (Gate 2)")
        a("")
        a("| Measure | Value |")
        a("| -- | --: |")
        for k, v in r["profile"].items():
            a(f"| {k} | {_f(v, 6)} |")
        a("")
    if "conversion" in r:
        c = r["conversion"]
        a("## Schema-v2 conversion")
        a("")
        a(f"Converted: **{c['converted']}**.")
        a("")
        for b in c["blockers"]:
            a(f"* BLOCKER: {b}")
        a("")
        a("| Determination | Decision |")
        a("| -- | -- |")
        for d in c["determinations"]:
            a(f"| {d['field']} | {d['decision']} |")
        a("")
    if "source_qc" in r:
        q = r["source_qc"]
        a(f"## Source-level QC (rules v{q['rules_version']}): verdict `{q['verdict']}`")
        a("")
        a("| Rule | Check | Severity | Status | Values | Detail |")
        a("| -- | -- | -- | -- | -- | -- |")
        for x in q["results"]:
            vals = ", ".join(f"{k}={_f(v)}" for k, v in x["values"].items())
            a(
                f"| {x['rule_id']} | `{x['name']}` | {x['severity']} | **{x['status']}** | {vals} "
                f"| {x['detail']} |"
            )
        a("")
    if "bundle_qc" in r:
        q = r["bundle_qc"]
        a(f"## Bundle QC: verdict `{q['verdict']}`")
        a("")
        for x in q["results"]:
            a(f"* {x['rule_id']} `{x['name']}` [{x['severity']}]: **{x['status']}** {x['detail']}")
        a("")
    if "diagnostics" in r:
        _diagnostics(a, r["diagnostics"])
    return "\n".join(L).rstrip() + "\n"


def _diagnostics(a: Any, d: dict[str, Any]) -> None:
    a("## Numerical diagnostics (pipeline-derived)")
    a("")
    p = d["package_preprocessing"]
    a("### Package preprocessing (arithmetic reproduction; R script not executed)")
    a("")
    for k, v in p.items():
        a(f"* {k}: {_f(v, 7)}")
    a("")
    tb = d["distance_velocity_time_base"]
    a("### Time-base agreement between vendor distance and vendor velocity")
    a("")
    a(
        f"* RMS(d(distance)/dt - velocity), 25 ms half-window: {_f(tb['rms_at_zero_lag_m_s'])} m/s "
        f"at zero lag; {_f(tb['rms_at_best_lag_m_s'])} m/s at best lag "
        f"**{_f(tb['best_lag_ms'])} ms** ({tb['sign']}; search ±{_f(tb['search_range_ms'])} ms)"
    )
    a(
        f"* distance first exceeds 0.5 m at {_f(tb['first_time_distance_above_0_5_m_s'])} s; "
        f"velocity first exceeds 1 m/s at {_f(tb['first_time_velocity_above_1_m_s'])} s"
    )
    a(
        "* The cause cannot be identified from manufacturer-processed exports. Any estimand "
        "that depends on the time origin (TD, split times read from distance, the "
        "distance-defined 30 m cut below) depends on which vendor channel defines t0."
    )
    a("")
    a(
        f"* Temporal qualification: **{tb['temporal_qualification']}** (tolerance "
        f"±{_f(tb['tolerance_ms'])} ms); timestamps modified: {tb['timestamps_modified']}; "
        f"lag applied to any output: {tb['lag_applied_to_any_output']}"
    )
    a("")
    joint = d["joint_distance_velocity_reconstruction"]
    a(f"> **{joint['statement']}**")
    a(">")
    a(
        "> Affected outputs (reported unshifted, at zero lag): "
        + ", ".join(f"`{x}`" for x in joint["affected_outputs"])
    )
    a("")
    a("### d(distance)/dt versus vendor velocities, by half-window (joint: see qualification)")
    a("")
    a(
        "| Half-window ms | Quantisation floor RMS m/s | vs velocity RMS / mean / max | "
        "vs unsmoothed RMS / mean / max |"
    )
    a("| --: | --: | --: | --: |")
    for row in d["distance_derivative_vs_vendor_velocity"]:
        s, u = row["vs_velocity"], row["vs_velocity_vendor_unsmoothed"]
        a(
            f"| {row['half_window_ms']} | {_f(row['quantisation_floor_rms_m_s'])} | "
            f"{_f(s['rms'])} / {_f(s['mean'])} / {_f(s['max_abs'])} | "
            f"{_f(u['rms'])} / {_f(u['mean'])} / {_f(u['max_abs'])} |"
        )
    a("")
    a("### Integrated vendor velocity versus vendor distance (joint: see qualification)")
    a("")
    for name, x in d["integrated_velocity_vs_distance"].items():
        a(
            f"* `{name}`: end difference {_f(x['end_difference_m'])} m, "
            f"max |difference| {_f(x['max_abs_difference_m'])} m"
        )
    a("")
    sv = d["smoothed_vs_unsmoothed_velocity"]
    a("### Smoothed versus unsmoothed vendor velocity")
    a("")
    a(
        f"* RMS {_f(sv['rms'])} m/s, mean {_f(sv['mean'])} m/s, max |Δ| {_f(sv['max_abs'])} m/s; "
        f"best alignment lag {_f(sv['best_alignment_lag_ms'])} ms ({sv['sign']}), "
        f"RMS there {_f(sv['rms_at_best_lag'])} m/s"
    )
    a("")
    a("### Derived acceleration peak: sensitivity to channel and derivative window")
    a("")
    for k, v in d["derived_acceleration_peak"].items():
        a(f"* {k}: {_f(v)}")
    a("")
    m = d["mono_exponential_fit_sensitivity"]
    a("### Mono-exponential model fit: sensitivity to preprocessing choice")
    a("")
    a(f"`v(t) = MSS·(1 - exp(-(t - TD)/TAU))`, least squares in MSS, TAU, TD. {m['note']}.")
    a("")
    a("| Variant | n | MSS m/s | TAU s | TD s | MAC m/s² | RMSE m/s |")
    a("| -- | --: | --: | --: | --: | --: | --: |")
    for name, f in m["variants"].items():
        a(
            f"| `{name}` | {f['n']} | {_f(f['mss_m_s'])} | {_f(f['tau_s'])} | {_f(f['td_s'])} | "
            f"{_f(f['mac_m_s2'])} | {_f(f['rmse_m_s'])} |"
        )
    a("")
    a(
        "Spread (max - min) across variants: "
        + ", ".join(f"{k} {_f(v)}" for k, v in m["spread"].items())
    )
    a("")
